import{d as h,C as t,o as g,c as d,j as i,a,E as e,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const z=JSON.parse('{"title":"中庸·第6章","description":"《中庸》第 6 章——舜之大知：不自用而取诸人，好问好察、隐恶扬善、执两用中。","frontmatter":{"title":"中庸·第6章","description":"《中庸》第 6 章——舜之大知：不自用而取诸人，好问好察、隐恶扬善、执两用中。","category":"guide","aliases":["第6章","中庸第6章","舜其大知"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-06.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-06.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-06.md"},b=h({...m,setup(p){const r=[{id:"zan",label:"舜其大知也与",showLabel:!0,sentences:[["子曰：“舜其",{text:"大知",glossary:"dazhi"},"也",{text:"与",glossary:"yu"},"！"]],note:"孔子赞舜：「舜其大知也与！」——舜大概真是大智之人吧！下文即说他何以堪称大知。"},{id:"suoyi",label:"好问好察 · 隐恶扬善 · 执两用中",showLabel:!0,sentences:[["舜",{text:"好问",glossary:"haowen"},"而好察",{text:"迩言",glossary:"eryan"},"，",{text:"隐恶而扬善",glossary:"yineyangshan"},"，",{text:"执其两端",glossary:"zhiliangduan"},"，",{text:"用其中",glossary:"yongqizhong"},"于民，其斯以为舜乎！”"]],note:"舜之所以为大知：好问（肯向人请教），好察迩言（连浅近的话也细加审察），隐恶而扬善（隐去别人的不善、宣扬其善），执其两端而用其中于民（把握过与不及两端，取中道施行于民）——这就是舜之所以为舜。"}],s=[{id:"shun",term:"舜",pinyin:"shùn",meaning:"虞舜，古圣王。朱注以舜、颜渊、子路分属知、仁、勇三达德，此章正举「知」。"},{id:"dazhi",term:"大知",pinyin:"dà zhì",meaning:"大智。「知」此处通「智」，读 zhì。朱注：「舜之所以为大知者，以其不自用而取诸人也。」"},{id:"yu",term:"与",pinyin:"yú",meaning:"同「欤」，句末语气词，表赞叹。读 yú。"},{id:"haowen",term:"好问",pinyin:"hào wèn",meaning:"喜欢请教别人。好：音 hào（喜好）。"},{id:"eryan",term:"迩言",pinyin:"ěr yán",meaning:"浅近之言。迩：近。朱注：「迩言者，浅近之言，犹必察焉，其无遗善可知。」"},{id:"yineyangshan",term:"隐恶而扬善",pinyin:"yǐn è ér yáng shàn",meaning:"隐去（他人言之）不善者，宣扬其善者。朱注：「其广大光明又如此，则人孰不乐告以善哉。」"},{id:"zhiliangduan",term:"执其两端",pinyin:"zhí qí liǎng duān",meaning:"把握两种极端。朱注：「两端，谓众论不同之极致。」即把各种主张的两极都拿到手。"},{id:"yongqizhong",term:"用其中",pinyin:"yòng qí zhōng",meaning:"取中道而用之。朱注：「于善之中又执其两端，而量度以取中，然后用之」——不是折中，是审择之后的恰当。"}];return(y,n)=>{const l=t("DaoTextReading"),o=t("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第6章",tabindex:"-1"},[a("中庸·第6章 "),i("a",{class:"header-anchor",href:"#中庸·第6章","aria-label":'Permalink to "中庸·第6章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("本章以舜为例，说「大知」是什么样：不在自己聪明，而在"),i("strong",null,"不自用而取诸人"),a("——好问、好察、隐恶扬善，最后落到「执其两端，用其中于民」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(l,{colophon:"舜其大知 · 执两用中",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第6章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(o,{items:[{term:"大知",pinyin:["dà","zhì"],meaning:"大智。「知」通「智」，读 zhì。朱注：「舜之所以为大知者，以其不自用而取诸人也。」"},{term:"与",pinyin:["yú"],meaning:"同「欤」，句末语气词，表赞叹。"},{term:"好问",pinyin:["hào","wèn"],meaning:"喜欢请教别人。好：音 hào（喜好）。"},{term:"迩言",pinyin:["ěr","yán"],meaning:"浅近之言。迩：近。连浅近的话也必审察，可见其无遗善。"},{term:"隐恶而扬善",pinyin:["yǐn","è","ér","yáng","shàn"],meaning:"隐去他人言之不善者，宣扬其善者——使人乐于进言。"}]}),e(o,{items:[{term:"执其两端",pinyin:["zhí","qí","liǎng","duān"],meaning:"把握众论的两极。朱注：「两端，谓众论不同之极致。」先把两头的道理都拿到手。"},{term:"用其中",pinyin:["yòng","qí","zhōng"],meaning:"取中道而用之。朱注：「于善之中又执其两端，而量度以取中，然后用之」——是审择后的恰当，不是折中。"},{term:"其斯以为舜乎",pinyin:["qí","sī","yǐ","wéi","shùn","hū"],meaning:"这大概就是他成为舜的原因吧。斯：此。"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>舜其大知也与</strong>：孔子说：「舜真是大智啊！」</p><p><strong>好问好察 · 隐恶扬善 · 执两用中</strong>：舜喜欢请教别人，又喜欢审察浅近的话；隐去别人说得不好的地方，宣扬好的地方；把握住两种极端，取中道用在百姓身上——这大概就是他成为舜的原因吧。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第六章给「大知」下了一个具体的定义。它不说舜有多聪明，而是数了他的四件事：<strong>好问、好察迩言、隐恶扬善、执两用中</strong>。</p><p>承第四章「知者过之」而来——聪明人容易「过」，舜之为大知，恰在于不靠自己一个人的聪明。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「大知」是不自用</strong>：朱注一句点透——「以其不自用而取诸人也」。真正的智，是把自己的判断先放下，把众人的话收进来。</li><li><strong>「隐恶扬善」不只是德行，也是方法</strong>：它让人肯说。朱注说得直白：「其广大光明又如此，则人孰不乐告以善哉？」——愿意听、且不拿别人的短处说事，好话才源源而来。</li><li><strong>「执其两端，用其中」不是折中</strong>：朱注特别解释了次序——先把「众论不同之极致」都执在手里，再「量度以取中」。<strong>先拿到两端，才谈得上取中</strong>。这与第四章的「过与不及」正成对照：不是取中间值，而是审择之后的恰当。</li><li><strong>知、仁、勇的排布</strong>：朱注说此篇以三达德为人道之门，故篇首即以大舜（知）、颜渊（仁）、子路（勇）之事明之。第六章正是其中的「知」。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>先不自用</strong>：做判断前，问自己「我听过几种不同的声音」。</li><li><strong>把两端都拿到手</strong>：觉得两难时，往往是因为只看到一端；先把对立的两极都听完，中才有落脚处。</li><li><strong>隐恶扬善是环境工程</strong>：想让身边人肯说真话，先做到不拿别人的短处当谈资。</li><li><strong>别把「聪明」当大知</strong>：自作聪明恰恰是第四章里「知者过之」的样子。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子赞叹：舜真是大智啊！</p><p>他的大智长什么样？——喜欢请教人，连浅近的话也认真听；隐去别人说得不好的，宣扬别人说得好的；把众说纷纭的两头都拿在手里，然后<strong>量度取中</strong>，用在百姓身上。这就是他之所以成为舜的原因。</p><p>一句话：<strong>大知不是自己更聪明，而是能不靠自己一个人聪明。</strong>「执两用中」也不是和稀泥——先有两端，才有中。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「不自用而取诸人」——我在什么事上最不肯听人？为什么？</li><li>「执其两端」——我最近做过的一个判断，两端都听全了吗？还是只听了自己愿意听的？</li><li>「隐恶扬善」——把它当方法看：我身边肯对我说真话的人，是多了还是少了？这与我自己有没有关系？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-05">中庸·第5章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-07">中庸·第7章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',22))])}}});export{z as __pageData,b as default};
